inline void Workspace::click_map(court_map::Point p){if(state_.view=="competitions")return;auto& camera=state_.depth?state_.area_camera:state_.world_camera;const auto world=camera.inverse(p);std::string id;auto hit=[&](const court_map::Node& node){if(court_map::contains(node,world))id=state_.depth?court_map::castle_id(state_.area,node):node.id;};if(state_.depth)for(const auto& node:court_map::castle_nodes)hit(node);else for(const auto& node:court_map::world_nodes)hit(node);if(id.empty())return;const auto i=std::find_if(cards_.begin(),cards_.end(),[&](const auto& c){return c.id==id;});if(i==cards_.end()||!flag(i->value,"enabled")){hint(state_.depth?"This Castle is inactive.":"This Area is inactive.");return;}if(camera.scale()*(state_.depth?124./1882.:136./2048.)<48&&camera.zoom<8){camera.zoom_at(1.8,p);map();hint("Zoomed in. Tap the location, or use List.");return;}state_.selected=id;if(state_.depth==0&&team_id().empty())hint("Join a Team first.");detail();actions();map();}
